    listRewind(selector->patterns,&li);
    while((ln = listNext(&li))) {
        keyPattern *thispat = (keyPattern *)listNodeValue(ln);
        res = sdsCatPatternString(res, thispat);
        res = sdscatlen(res," ",1);
    }
    return res;
}

static sds aclHubRewriteDescribeSelectorChannels(aclSecurityHub *hub, aclSelector *selector, sds res) {
    listIter li;
    listNode *ln;
    hub->rewrite_selector = selector;
    if (selector->flags & SELECTOR_FLAG_ALLCHANNELS) {
        res = sdscatlen(res,"&* ",3);
        return res;
    }
    res = sdscatlen(res,"resetchannels ",14);
    listRewind(selector->channels,&li);
    while((ln = listNext(&li))) {
        sds thispat = listNodeValue(ln);
        res = sdscatlen(res,"&",1);
        res = sdscatsds(res,thispat);
        res = sdscatlen(res," ",1);
    }
    return res;
}

static sds aclHubRewriteDescribeSelector(aclSecurityHub *hub, aclSelector *selector) {
    sds res;
    sds rules;
    hub->rewrite_selector = selector;
    res = sdsempty();
    res = aclHubRewriteDescribeSelectorKeys(hub, selector, res);
    res = aclHubRewriteDescribeSelectorChannels(hub, selector, res);
    rules = aclHubRewriteDescribeCommandRules(hub, selector);
    hub->rewrite_rules = rules;
    res = sdscatsds(res,rules);
    sdsfree(rules);
    hub->rewrite_rules = NULL;
    return res;
}

